// 数组创建与初始化
int[] arr1 = new int[5];              // [0, 0, 0, 0, 0]
int[] arr2 = {1, 2, 3, 4, 5};        // 直接初始化
int[] arr3 = new int[]{1, 2, 3};      // 匿名数组

// 二维数组
int[][] matrix = {
    {1, 2, 3},
    {4, 5, 6},
    {7, 8, 9}
};

// 常用操作
Arrays.sort(arr2);                     // 排序 O(n log n)
Arrays.fill(arr1, -1);                 // 填充
int[] copy = Arrays.copyOf(arr2, 3);   // 复制前3个元素
int idx = Arrays.binarySearch(arr2, 3); // 二分查找（需已排序）

// 遍历方式
for (int i = 0; i < arr2.length; i++) { System.out.println(arr2[i]); }
for (int num : arr2) { System.out.println(num); }
